# OpenDraft Article Release SHACL Shapes
#
# Release-only constraints split out of protocol/article.shacl.ttl
# (T26): a draft validates against article.shacl.ttl alone, a release
# against the union of both files. A graph is a release iff its
# od:Publication carries a DOI identifier (dcterms:identifier or
# datacite:hasIdentifier) or realizes a fabio:Work via
# frbr:realizationOf. Drafts may omit the repository URL and source
# revision; releases must declare them. The authorship minimums (at
# least one creator, at least one author role, one oco:hasNext chain
# head and one corresponding author with a mailbox) are release-only
# too: a draft may still be gathering authors (ADR-026).
# SHACL Core only (no SHACL-SPARQL); assumes one publication per graph.

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix od: <https://w3id.org/opendraft/ontology#> .
@prefix fabio: <http://purl.org/spar/fabio/> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix frbr: <http://purl.org/vocab/frbr/core#> .
@prefix datacite: <http://purl.org/datacite/ontology/> .
@prefix literal: <https://w3id.org/literal/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix doco: <http://purl.org/spar/doco/> .
@prefix pro: <http://purl.org/spar/pro/> .
@prefix scoro: <http://purl.org/spar/scoro/> .
@prefix oco: <https://w3id.org/oc/ontology/> .
@prefix foaf: <http://xmlns.com/foaf/0.1/> .

# =============================================================================
# Release Provenance Shape — repository URL and source revision
#
# Split from od:PublicationShape: drafts compile without a repository
# or a pinned Git commit, releases must record both (ADR-018).
# =============================================================================

od:PublicationReleaseShape
    a sh:NodeShape ;
    sh:targetClass od:Publication ;

    sh:property [
        sh:path od:repositoryUrl ;
        sh:datatype xsd:anyURI ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:message "A release must have exactly one repository URL with datatype xsd:anyURI." ;
    ] ;
    sh:property [
        sh:path od:sourceRevision ;
        sh:datatype xsd:string ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:pattern "^[0-9a-f]{40}$" ;
        sh:message "A release must have exactly one source revision: a 40-character hexadecimal Git commit SHA." ;
    ] .

# =============================================================================
# Work / Version Shape — FRBR Work–Expression model (ADR-021)
#
# The manuscript is a fabio:Work (concept DOI); each published version
# is an od:Publication that realizes exactly one Work and may revise at
# most one earlier version. A publication IRI can never double as its
# own Work IRI (concept and version DOIs must differ).
# =============================================================================

od:PublicationWorkShape
    a sh:NodeShape ;
    sh:targetClass od:Publication ;

    sh:property [
        sh:path frbr:realizationOf ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:qualifiedValueShape [
            a sh:NodeShape ;
            sh:class fabio:Work ;
        ] ;
        sh:qualifiedMinCount 1 ;
        sh:message "A release must have exactly one frbr:realizationOf pointing to a fabio:Work." ;
    ] ;
    sh:property [
        sh:path frbr:revisionOf ;
        sh:maxCount 1 ;
        sh:message "A release may revise at most one earlier version (frbr:revisionOf)." ;
    ] ;
    sh:not [
        a sh:NodeShape ;
        sh:class fabio:Work ;
    ] ;
    sh:message "A publication IRI must differ from its Work IRI: an od:Publication may not also be a fabio:Work." .

# =============================================================================
# Identifier Shape — classic dcterms:identifier or OCDM identifier nodes
# =============================================================================

od:PublicationIdentifierShape
    a sh:NodeShape ;
    sh:targetClass od:Publication ;

    sh:property [
        sh:path datacite:hasIdentifier ;
        sh:node [
            a sh:NodeShape ;
            sh:property [
                sh:path datacite:usesIdentifierScheme ;
                sh:minCount 1 ;
                sh:message "An OCDM identifier node must declare datacite:usesIdentifierScheme." ;
            ] ;
            sh:property [
                sh:path literal:hasLiteralValue ;
                sh:minCount 1 ;
                sh:message "An OCDM identifier node must declare literal:hasLiteralValue." ;
            ] ;
        ] ;
        sh:message "A datacite:hasIdentifier node must declare a scheme and a literal value." ;
    ] ;
    sh:or (
        [ sh:property [ sh:path dcterms:identifier ; sh:minCount 1 ] ]
        [ sh:property [ sh:path datacite:hasIdentifier ; sh:minCount 1 ] ]
    ) ;
    sh:message "A release must declare at least one identifier: dcterms:identifier or an OCDM datacite:hasIdentifier node." .

# =============================================================================
# Section Source Shape — releases pin every section to its block file
#
# Drafts may omit section sources (article.shacl.ttl allows an
# optional https dcterms:source); a release must declare the raw
# block-file URL for every doco:Section (ADR-018 provenance).
# =============================================================================

od:SectionSourceShape
    a sh:NodeShape ;
    sh:targetClass doco:Section ;

    sh:property [
        sh:path dcterms:source ;
        sh:minCount 1 ;
        sh:message "A release section must declare its dcterms:source block file IRI." ;
    ] .

# =============================================================================
# Authorship Shape — releases must declare a complete authorship graph
#
# Split from od:PublicationShape and od:PublicationAuthorshipShape: a
# draft may omit creators and roles entirely, while a release must
# carry at least one dcterms:creator, an author role, exactly one head
# of the oco:hasNext author chain and a corresponding author reachable
# by email (ADR-021, ADR-026).
# =============================================================================

od:PublicationAuthorshipReleaseShape
    a sh:NodeShape ;
    sh:targetClass od:Publication ;

    sh:property [
        sh:path dcterms:creator ;
        sh:minCount 1 ;
        sh:message "A publication must have at least one creator." ;
    ] ;

    # At least one author role in the document context.
    sh:property [
        sh:path pro:isDocumentContextFor ;
        sh:qualifiedValueShape [
            sh:path pro:withRole ;
            sh:hasValue pro:author ;
        ] ;
        sh:qualifiedMinCount 1 ;
        sh:message "A publication must have at least one author role (pro:withRole pro:author)." ;
    ] ;

    # Exactly one author role heads the chain (no incoming oco:hasNext).
    sh:property [
        sh:path pro:isDocumentContextFor ;
        sh:qualifiedValueShape [
            a sh:NodeShape ;
            sh:property [
                sh:path pro:withRole ;
                sh:hasValue pro:author ;
            ] ;
            sh:property [
                sh:path [ sh:inversePath oco:hasNext ] ;
                sh:maxCount 0 ;
            ] ;
        ] ;
        sh:qualifiedMinCount 1 ;
        sh:message "Exactly one author role must head the oco:hasNext author chain." ;
    ] ;

    # At least one corresponding-author role whose holder has a mailbox.
    sh:property [
        sh:path pro:isDocumentContextFor ;
        sh:qualifiedValueShape [
            a sh:NodeShape ;
            sh:property [
                sh:path pro:withRole ;
                sh:hasValue scoro:corresponding-author ;
            ] ;
            sh:property [
                sh:path pro:isHeldBy ;
                sh:qualifiedValueShape [
                    sh:path foaf:mbox ;
                    sh:minCount 1 ;
                ] ;
                sh:qualifiedMinCount 1 ;
            ] ;
        ] ;
        sh:qualifiedMinCount 1 ;
        sh:message "A publication must have at least one corresponding-author role whose holder has a foaf:mbox." ;
    ] .

objects.238165cae4b81c6dd5a0a1c8a97d005b08bb3690:
# OpenDraft Article SHACL Shapes
#
# Validates that an article RDF graph conforms to the OpenDraft protocol.
# Phase 01: full required field set plus optional-field capability shapes.
# Provenance scalars live directly on od:Publication (see ADR-018).
# Release-only constraints (identifier, FRBR work, od:repositoryUrl,
# od:sourceRevision, and the authorship minimums) live in
# protocol/article-release.shacl.ttl.
# ADR-021: authorship follows the OCDM role model — every role node is
# linked from the publication via pro:isDocumentContextFor, roles are
# held by agents (pro:isHeldBy), and author order is an oco:hasNext
# chain between roles carrying pro:withRole pro:author.
# SHACL Core only (no SHACL-SPARQL); assumes one publication per graph.

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix od: <https://w3id.org/opendraft/ontology#> .
@prefix fabio: <http://purl.org/spar/fabio/> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix doco: <http://purl.org/spar/doco/> .
@prefix deo: <http://purl.org/spar/deo/> .
@prefix pro: <http://purl.org/spar/pro/> .
@prefix scoro: <http://purl.org/spar/scoro/> .
@prefix oco: <https://w3id.org/oc/ontology/> .
@prefix foaf: <http://xmlns.com/foaf/0.1/> .
@prefix credit: <https://credit.niso.org/contributor-roles/> .
@prefix frbr: <http://purl.org/vocab/frbr/core#> .
@prefix cito: <http://purl.org/spar/cito/> .
@prefix datacite: <http://purl.org/datacite/ontology/> .
@prefix literal: <https://w3id.org/literal/> .
@prefix prism: <http://prismstandard.org/namespaces/basic/2.0/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

# =============================================================================
# Publication Shape — required fields
# =============================================================================

od:PublicationShape
    a sh:NodeShape ;
    sh:targetClass od:Publication ;

    sh:property [
        sh:path dcterms:title ;
        sh:datatype xsd:string ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:message "A publication must have exactly one title." ;
    ] ;
    sh:property [
        sh:path od:manuscriptPath ;
        sh:datatype xsd:string ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:message "A publication must have exactly one manuscript path." ;
    ] ;
    sh:property [
        sh:path dcterms:conformsTo ;
        sh:nodeKind sh:IRI ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:pattern "^https://github\\.com/[^/]+/[^/]+/tree/[0-9a-f]{40}/protocol$" ;
        sh:message "A publication must have exactly one dcterms:conformsTo IRI: https://github.com/<owner>/<repo>/tree/<40-character SHA>/protocol." ;
    ] ;
    sh:property [
        sh:path dcterms:hasPart ;
        sh:class doco:Section ;
        sh:message "dcterms:hasPart values must be doco:Section nodes." ;
    ] .
    # Release-only constraints (identifier, frbr:realizationOf,
    # od:repositoryUrl, od:sourceRevision) live in
    # protocol/article-release.shacl.ttl; drafts validate without them.

# =============================================================================
# License and Citation Shapes — warnings (do not affect conformance)
# =============================================================================

od:PublicationLicenseShape
    a sh:NodeShape ;
    sh:targetClass od:Publication ;

    sh:property [
        sh:path dcterms:license ;
        sh:minCount 1 ;
        sh:severity sh:Warning ;
        sh:message "A publication should declare a dcterms:license." ;
    ] .

od:PublicationCitationShape
    a sh:NodeShape ;
    sh:targetClass od:Publication ;

    sh:property [
        sh:path cito:cites ;
        sh:not [
            a sh:NodeShape ;
            sh:class fabio:Work ;
        ] ;
        sh:severity sh:Warning ;
        sh:message "cito:cites should target a specific version (version DOI), not the fabio:Work concept." ;
    ] .

# =============================================================================
# Publication Shape — optional fields
# =============================================================================

od:PublicationOptionalShape
    a sh:NodeShape ;
    sh:targetClass od:Publication ;

    sh:property [
        sh:path dcterms:abstract ;
        sh:maxCount 1 ;
        sh:message "A publication may have at most one abstract." ;
    ] .

# =============================================================================
# Publication Shape — informational (non-enforcing) capability notes
# =============================================================================

od:PublicationInfoShape
    a sh:NodeShape ;
    sh:targetClass od:Publication ;
    sh:severity sh:Info ;

    sh:property [
        sh:path fabio:hasSubjectTerm ;
        sh:message "Subject terms may be expressed via fabio:hasSubjectTerm pointing to a SKOS subject term." ;
    ] ;
    sh:property [
        sh:path prism:keyword ;
        sh:message "Keywords are informational and may be expressed via prism:keyword." ;
    ] ;
    sh:property [
        sh:path dcterms:references ;
        sh:message "References may be expressed via dcterms:references." ;
    ] .

# =============================================================================
# Authorship Shapes — OCDM author role model (ADR-021)
#
# Authorship roles are pro:RoleInTime nodes reachable from the
# publication via pro:isDocumentContextFor. The author order is a single
# oco:hasNext chain between roles carrying pro:withRole pro:author.
# The authorship minimums (at least one creator, at least one author
# role, one chain head, one corresponding author with a mailbox) are
# release-only and live in protocol/article-release.shacl.ttl: a draft
# may still be gathering authors (ADR-026). The shapes here only
# constrain roles that exist.
# =============================================================================

od:PublicationAuthorshipShape
    a sh:NodeShape ;
    sh:targetClass od:Publication ;

    # At most one author role heads the chain (no incoming oco:hasNext).
    sh:property [
        sh:path pro:isDocumentContextFor ;
        sh:qualifiedValueShape [
            a sh:NodeShape ;
            sh:property [
                sh:path pro:withRole ;
                sh:hasValue pro:author ;
            ] ;
            sh:property [
                sh:path [ sh:inversePath oco:hasNext ] ;
                sh:maxCount 0 ;
            ] ;
        ] ;
        sh:qualifiedMaxCount 1 ;
        sh:message "Exactly one author role may head the oco:hasNext author chain." ;
    ] ;

    # An author role must be held by a named agent (person or group).
    sh:property [
        sh:path pro:isDocumentContextFor ;
        sh:qualifiedValueShape [
            a sh:NodeShape ;
            sh:property [
                sh:path pro:withRole ;
                sh:hasValue pro:author ;
            ] ;
            sh:property [
                sh:path pro:isHeldBy ;
                sh:not [
                    a sh:NodeShape ;
                    sh:or (
                        [ sh:path foaf:familyName ; sh:minCount 1 ]
                        [ sh:path foaf:name ; sh:minCount 1 ]
                    ) ;
                ] ;
            ] ;
        ] ;
        sh:qualifiedMaxCount 0 ;
        sh:message "An author role must be held by an agent with a foaf:familyName or foaf:name." ;
    ] ;

    # A person author must hold a scoro:affiliate role (groups exempt).
    sh:property [
        sh:path pro:isDocumentContextFor ;
        sh:qualifiedValueShape [
            a sh:NodeShape ;
            sh:property [
                sh:path pro:withRole ;
                sh:hasValue pro:author ;
            ] ;
            sh:property [
                sh:path pro:isHeldBy ;
                sh:not [
                    a sh:NodeShape ;
                    sh:or (
                        [ sh:class foaf:Group ]
                        [ sh:property [
                            sh:path [ sh:inversePath pro:isHeldBy ] ;
                            sh:qualifiedValueShape [
                                sh:path pro:withRole ;
                                sh:hasValue scoro:affiliate ;
                            ] ;
                            sh:qualifiedMinCount 1 ;
                        ] ]
                    ) ;
                ] ;
            ] ;
        ] ;
        sh:qualifiedMaxCount 0 ;
        sh:message "A person author must hold a scoro:affiliate role linked to an organization." ;
    ] ;

    # An affiliate role has exactly one organization with a foaf:name;
    # no context role may be an affiliate role lacking one.
    sh:property [
        sh:path pro:isDocumentContextFor ;
        sh:qualifiedValueShape [
            a sh:NodeShape ;
            sh:property [
                sh:path pro:withRole ;
                sh:hasValue scoro:affiliate ;
            ] ;
            sh:not [
                a sh:NodeShape ;
                sh:property [
                    sh:path pro:relatesToOrganization ;
                    sh:minCount 1 ;
                    sh:maxCount 1 ;
                    sh:node [
                        sh:property [
                            sh:path foaf:name ;
                            sh:minCount 1 ;
                        ] ;
                    ] ;
                ] ;
            ] ;
        ] ;
        sh:qualifiedMaxCount 0 ;
        sh:message "An affiliate role must have exactly one organization with a foaf:name." ;
    ] .

# On-behalf-of authors are modeled as an extra scoro:agent role in the
# document context: held by the author (pro:isHeldBy) and related to the
# group (pro:relatesToEntity). It never joins the oco:hasNext chain —
# the chain shapes above only match roles carrying pro:withRole pro:author.
od:AuthorshipRoleShape
    a sh:NodeShape ;
    sh:targetClass pro:RoleInTime ;

    sh:property [
        sh:path pro:isHeldBy ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:message "Every authorship role must have exactly one holder (pro:isHeldBy)." ;
    ] ;
    sh:property [
        sh:path oco:hasNext ;
        sh:maxCount 1 ;
        sh:message "A role may have at most one successor in the author chain (oco:hasNext)." ;
    ] ;
    sh:property [
        sh:path [ sh:inversePath oco:hasNext ] ;
        sh:maxCount 1 ;
        sh:message "A role may have at most one predecessor in the author chain." ;
    ] ;
    sh:property [
        sh:path pro:withRole ;
        sh:in (
            pro:author
            scoro:agent
            scoro:corresponding-author
            scoro:affiliate
            scoro:consortium-author
            credit:conceptualization
            credit:data-curation
            credit:formal-analysis
            credit:funding-acquisition
            credit:investigation
            credit:methodology
            credit:project-administration
            credit:resources
            credit:software
            credit:supervision
            credit:validation
            credit:visualization
            credit:writing-original-draft
            credit:writing-review-editing
        ) ;
        sh:message "Role values (pro:withRole) are restricted to PRO/SCoRO authorship roles and the 14 NISO CRediT roles." ;
    ] .

od:GroupShape
    a sh:NodeShape ;
    sh:targetClass foaf:Group ;

    sh:property [
        sh:path foaf:name ;
        sh:minCount 1 ;
        sh:message "A foaf:Group author must have a foaf:name." ;
    ] .

# =============================================================================
# Section Shape — manuscript sections (doco:Section, deo roles)
#
# A section is linked from its publication via dcterms:hasPart,
# titled exactly once, carrying at most one deo role class, chained
# to its successor with oco:hasNext, and sourced over https. The
# release-only dcterms:source requirement lives in
# protocol/article-release.shacl.ttl.
# =============================================================================

od:SectionShape
    a sh:NodeShape ;
    sh:targetClass doco:Section ;

    sh:property [
        sh:path dcterms:title ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:message "A section must have exactly one dcterms:title." ;
    ] ;
    sh:property [
        sh:path rdf:type ;
        sh:qualifiedValueShape [
            sh:in (
                deo:Introduction
                deo:Methods
                deo:Results
                deo:Discussion
                deo:Conclusion
                deo:Acknowledgements
                deo:AuthorContribution
                deo:Background
                deo:Biography
                deo:Contribution
                deo:Data
                deo:DatasetDescription
                deo:Dedication
                deo:Epilogue
                deo:Evaluation
                deo:ExternalResourceDescription
                deo:FutureWork
                deo:Materials
                deo:Model
                deo:Motivation
                deo:Postscript
                deo:ProblemStatement
                deo:Prologue
                deo:RelatedWork
                deo:Scenario
                deo:SupplementaryInformationDescription
            ) ;
        ] ;
        sh:qualifiedMaxCount 1 ;
        sh:message "A section may have at most one deo role class." ;
    ] ;
    sh:property [
        sh:path oco:hasNext ;
        sh:maxCount 1 ;
        sh:class doco:Section ;
        sh:message "A section may have at most one successor section (oco:hasNext)." ;
    ] ;
    sh:property [
        sh:path [ sh:inversePath oco:hasNext ] ;
        sh:maxCount 1 ;
        sh:message "A section may have at most one predecessor section (oco:hasNext)." ;
    ] ;
    sh:property [
        sh:path dcterms:source ;
        sh:maxCount 1 ;
        sh:nodeKind sh:IRI ;
        sh:pattern "^https://" ;
        sh:message "A section dcterms:source must be an IRI starting with https://." ;
    ] .

objects.89d71b33688cad5648dd795ae2e7f274640f5e82:
# OpenDraft Example Article
#
# A canonical example publication demonstrating the OCDM authorship
# pattern (ADR-021): author roles linked from the publication via
# pro:isDocumentContextFor, ordered in a single oco:hasNext chain, and
# held by agents (pro:isHeldBy). Affiliations are scoro:affiliate roles
# relating the author to a ROR-identified organization.
#
# Demonstrates: an ORCID corresponding author, a non-ORCID person
# writing on behalf of a named group, a group author with members,
# equal contribution (scoro:isEqualToRoleInTime), affiliations shared
# between authors, CRediT roles, keywords, and a subject assignment
# recorded as a W3C Web Annotation (oa:classifying).
#
# Validates clean against protocol/article.shacl.ttl.

@prefix od: <https://w3id.org/opendraft/ontology#> .
@prefix ex: <https://example.org/> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix fabio: <http://purl.org/spar/fabio/> .
@prefix pro: <http://purl.org/spar/pro/> .
@prefix scoro: <http://purl.org/spar/scoro/> .
@prefix oco: <https://w3id.org/oc/ontology/> .
@prefix foaf: <http://xmlns.com/foaf/0.1/> .
@prefix credit: <https://credit.niso.org/contributor-roles/> .
@prefix prism: <http://prismstandard.org/namespaces/basic/2.0/> .
@prefix frbr: <http://purl.org/vocab/frbr/core#> .
@prefix cito: <http://purl.org/spar/cito/> .
@prefix datacite: <http://purl.org/datacite/ontology/> .
@prefix literal: <https://w3id.org/literal/> .
@prefix frapo: <http://purl.org/spar/frapo/> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix oa: <http://www.w3.org/ns/oa#> .

# The Work behind the manuscript: one fabio:Work per manuscript with a
# concept DOI. Every published version realizes this Work; Work and
# Expression never share a DOI.
ex:example-work
    a fabio:Work ;
    dcterms:title "Example Publication: OpenDraft Protocol" ;
    dcterms:identifier <https://doi.org/10.5555/example-opendraft-concept> .

# The previous version (v1) of this publication: an earlier
# fabio:Expression revised by v2 below.
ex:example-publication-v1
    a fabio:Expression ;
    dcterms:identifier <https://doi.org/10.5555/example-opendraft-2026-v1> ;
    prism:versionIdentifier "1" .

# The publication itself. Identified by version DOI; carries full
# provenance scalars plus the authorship document context.
ex:example-publication
    a od:Publication ;

    dcterms:title "Example Publication: OpenDraft Protocol" ;
    dcterms:creator <https://orcid.org/0000-0002-1825-0097> ,
                    _:budi-lee ,
                    ex:group-who-diabetes ;
    dcterms:identifier <https://doi.org/10.5555/example-opendraft-2026> ;
    od:repositoryUrl "https://github.com/konsulin-care/opendraft"^^xsd:anyURI ;
    od:manuscriptPath "manuscripts/distributed-scientific-publication/article.qmd" ;
    od:sourceRevision "1a2b3c4d5e6f708192a3b4c5d6e7f8091a2b3c4d" ;
    dcterms:conformsTo <https://github.com/konsulin-care/opendraft/tree/0000000000000000000000000000000000000000/protocol> ;

    # Work/version identity: v2 realizes the Work and revises v1.
    frbr:realizationOf ex:example-work ;
    frbr:revisionOf ex:example-publication-v1 ;
    prism:versionIdentifier "2" ;

    # OCDM identifier node alongside the DOI IRI.
    datacite:hasIdentifier [
        datacite:usesIdentifierScheme datacite:doi ;
        literal:hasLiteralValue "10.5555/example-opendraft-2026" ;
    ] ;

    dcterms:license <http://creativecommons.org/licenses/by/4.0/> ;
    frapo:isFundedBy ex:example-grant ;
    cito:cites <https://doi.org/10.5555/related-study-2025> ;

    dcterms:abstract "A canonical example publication used to demonstrate the OpenDraft protocol." ;

    # Authorship roles live in the document context of the publication.
    pro:isDocumentContextFor ex:role-alice-author ,
                             ex:role-alice-ui ,
                             ex:role-alice-rscm ,
                             ex:role-budi-author ,
                             ex:role-budi-agent ,
                             ex:role-budi-rscm ,
                             ex:role-group-author ;

    prism:keyword "distributed scientific publication" ,
                  "research data" ;
    fabio:hasSubjectTerm ex:concept-distributed-scientific-publication ;
    dcterms:subject ex:concept-distributed-scientific-publication .

# The subject assignment as a W3C Web Annotation: the publication is
# classified with the SKOS subject term, with agent and timestamp.
[] a oa:Annotation ;
   oa:motivatedBy oa:classifying ;
   oa:hasTarget ex:example-publication ;
   oa:hasBody ex:concept-distributed-scientific-publication ;
   dcterms:creator <https://orcid.org/0000-0002-1825-0097> ;
   dcterms:created "2026-01-15T09:00:00"^^xsd:dateTime .

ex:concept-distributed-scientific-publication
    a skos:Concept , fabio:SubjectTerm ;
    skos:prefLabel "Distributed scientific publication"@en .

# --- Author order: Alice Marie Smith, Budi Lee, WHO Diabetes Work Group ---

# Head of the oco:hasNext author chain; also the corresponding author
# and an equal contributor. Carries CRediT roles alongside the PRO and
# SCoRO role values.
ex:role-alice-author
    a pro:RoleInTime ;
    pro:withRole pro:author ,
                 scoro:corresponding-author ,
                 credit:conceptualization ,
                 credit:writing-original-draft ;
    pro:isHeldBy <https://orcid.org/0000-0002-1825-0097> ;
    scoro:isEqualToRoleInTime ex:role-budi-author ;
    oco:hasNext ex:role-budi-author .

# Affiliate roles: one per affiliation, each pointing at one
# ROR-identified organization. Alice shares rscm with Budi.
ex:role-alice-ui
    a pro:RoleInTime ;
    pro:withRole scoro:affiliate ;
    pro:isHeldBy <https://orcid.org/0000-0002-1825-0097> ;
    pro:relatesToOrganization <https://ror.org/0116zj450> .

ex:role-alice-rscm
    a pro:RoleInTime ;
    pro:withRole scoro:affiliate ;
    pro:isHeldBy <https://orcid.org/0000-0002-1825-0097> ;
    pro:relatesToOrganization <https://ror.org/05dxgng32> .

<https://orcid.org/0000-0002-1825-0097>
    a foaf:Person ;
    foaf:givenName "Alice Marie" ;
    foaf:familyName "Smith" ;
    foaf:mbox <mailto:alice.smith@example.edu> ;
    datacite:hasIdentifier [
        datacite:usesIdentifierScheme datacite:orcid ;
        literal:hasLiteralValue "0000-0002-1825-0097" ;
    ] .

# Second author: no ORCID, holds the author role on behalf of the
# group, equal contributor, CRediT roles.
ex:role-budi-author
    a pro:RoleInTime ;
    pro:withRole pro:author ,
                 credit:investigation ,
                 credit:software ;
    pro:isHeldBy _:budi-lee ;
    scoro:isEqualToRoleInTime ex:role-alice-author ;
    oco:hasNext ex:role-group-author .

# On-behalf-of authorship as an extra scoro:agent role in the document
# context: held by the author and related to the group. It never joins
# the oco:hasNext chain.
ex:role-budi-agent
    a pro:RoleInTime ;
    pro:withRole scoro:agent ;
    pro:isHeldBy _:budi-lee ;
    pro:relatesToEntity ex:group-who-diabetes .

ex:role-budi-rscm
    a pro:RoleInTime ;
    pro:withRole scoro:affiliate ;
    pro:isHeldBy _:budi-lee ;
    pro:relatesToOrganization <https://ror.org/05dxgng32> .

# An agent without an identifier is modelled as a blank node.
_:budi-lee
    a foaf:Person ;
    foaf:givenName "Budi" ;
    foaf:familyName "Lee" .

# Tail of the author chain: a named group author with members.
ex:role-group-author
    a pro:RoleInTime ;
    pro:withRole pro:author ;
    pro:isHeldBy ex:group-who-diabetes .

ex:group-who-diabetes
    a foaf:Group ;
    foaf:name "WHO Diabetes Work Group" ;
    foaf:member _:member-sari , _:member-dewi .

# Shared affiliation organizations, identified by ROR IRI and named.
<https://ror.org/0116zj450>
    a foaf:Organization ;
    foaf:name "Universitas Indonesia" ;
    datacite:hasIdentifier [
        datacite:usesIdentifierScheme datacite:ror ;
        literal:hasLiteralValue "0116zj450" ;
    ] .

<https://ror.org/05dxgng32>
    a foaf:Organization ;
    foaf:name "Research Center for Climate Science" ;
    datacite:hasIdentifier [
        datacite:usesIdentifierScheme datacite:ror ;
        literal:hasLiteralValue "05dxgng32" ;
    ] .

# FRAPO funding: the publication is funded by a grant.
ex:example-grant
    a frapo:Grant ;
    dcterms:title "OpenDraft Example Grant" .

_:member-sari
    a foaf:Person ;
    foaf:givenName "Sari" ;
    foaf:familyName "Wijaya" .

_:member-dewi
    a foaf:Person ;
    foaf:givenName "Dewi" ;
    foaf:familyName "Suharto" .

objects.622a5179161fd5f316994063c8505fe174a61dc0:
# OpenDraft Example: Publication Registry
#
# A working example of a publication registry (OD-014). It is a
# fabio:ExpressionCollection whose frbr:part lists publications and
# must not contain other registries.
#
# Validates clean against protocol/registry.shacl.ttl.

@prefix od: <https://w3id.org/opendraft/ontology#> .
@prefix fabio: <http://purl.org/spar/fabio/> .
@prefix frbr: <http://purl.org/vocab/frbr/core#> .
@prefix dcterms: <http://purl.org/dc/terms/> .

# The publication registry itself. Lists publications available in a
# collection; the full publication description lives in
# protocol/examples/article.ttl.
<https://example.org/example-publication-registry>
    a fabio:ExpressionCollection ;
    dcterms:title "OpenDraft Example Publication Registry" ;
    dcterms:description "A publication registry containing example publications." ;
    frbr:part <https://example.org/example-publication> .

# The referenced article, typed inline so the frbr:part sh:class
# constraint holds within this file alone.
<https://example.org/example-publication>
    a od:Publication .

objects.a62c5548a982020f7e85ec99e02172530df39da8:
# OpenDraft Ontology
#
# The canonical RDF vocabulary for the OpenDraft protocol.
# Namespace: https://w3id.org/opendraft/ontology#
# Prefix: od:
#
# The protocol reuses established vocabularies instead of defining
# custom terms where possible (SPAR/OCDM alignment, ADR-021):
#   - SPAR: FaBiO (fabio: Expression, Work, SubjectTerm,
#     ExpressionCollection), FRBR (frbr: realizationOf, revisionOf,
#     part), PRO (pro: Role, RoleInTime, isHeldBy,
#     withRole), SCoRO (scoro: agent, corresponding-author, affiliate),
#     DOCO (doco: Section) and DEO (deo: section roles)
#   - OpenCitations: OCO (oco: hasNext for author order); OCDM patterns
#     via the DataCite (datacite:) and Literal (literal:) ontologies
#   - PRISM (prism: versionIdentifier, keyword), FRAPO (frapo: Grant),
#     CiTO (cito: cites), NISO CRediT (credit: contributor roles)
#   - Dublin Core Terms, FOAF, SKOS, PROV-O
#
# Prefixes for reused vocabularies are declared for reference only;
# this ontology does NOT owl:import them (reference-only prefixes).
#
# Custom od: terms cover only what existing vocabularies do not express:
#   - Git-specific provenance (source revision, repository URL); the
#     pinned protocol revision is expressed as dcterms:conformsTo
#   - Author flags: isDeceased
#
# Subject assignments follow the W3C Web Annotation Data Model
# (oa:Annotation motivated by oa:classifying); the oa: prefix below is
# declared for reference only.

@prefix od: <https://w3id.org/opendraft/ontology#> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix foaf: <http://xmlns.com/foaf/0.1/> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .
@prefix prov: <http://www.w3.org/ns/prov#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix fabio: <http://purl.org/spar/fabio/> .
@prefix frbr: <http://purl.org/vocab/frbr/core#> .
@prefix pro: <http://purl.org/spar/pro/> .
@prefix scoro: <http://purl.org/spar/scoro/> .
@prefix oco: <https://w3id.org/oc/ontology/> .
@prefix prism: <http://prismstandard.org/namespaces/basic/2.0/> .
@prefix frapo: <http://purl.org/spar/frapo/> .
@prefix cito: <http://purl.org/spar/cito/> .
@prefix datacite: <http://purl.org/datacite/ontology/> .
@prefix literal: <https://w3id.org/literal/> .
@prefix credit: <https://credit.niso.org/contributor-roles/> .
@prefix oa: <http://www.w3.org/ns/oa#> .
@prefix doco: <http://purl.org/spar/doco/> .
@prefix deo: <http://purl.org/spar/deo/> .


# =============================================================================
# CLASSES
# =============================================================================

od:Publication
    rdf:type owl:Class ;
    rdfs:subClassOf fabio:Expression ;
    rdfs:label "Publication" ;
    rdfs:comment "A published version of an article: one fabio:Expression that is the sole frbr:realizationOf a fabio:Work. Identified by its version DOI. Carries repository URL, source revision, and a dcterms:conformsTo link to the pinned protocol revision." .


# =============================================================================
# PROPERTIES — Publication provenance (flat scalars, see ADR-018)
# =============================================================================

od:repositoryUrl
    rdf:type owl:DatatypeProperty ;
    rdfs:domain od:Publication ;
    rdfs:range xsd:anyURI ;
    rdfs:label "repository URL" ;
    rdfs:comment "URL of the Git source repository that produced this publication." .

od:sourceRevision
    rdf:type owl:DatatypeProperty ;
    rdfs:domain od:Publication ;
    rdfs:range xsd:string ;
    rdfs:label "source revision" ;
    rdfs:comment "Full 40-character Git commit SHA of the source revision." .

od:manuscriptPath
    rdf:type owl:DatatypeProperty ;
    rdfs:domain od:Publication ;
    rdfs:range xsd:string ;
    rdfs:label "manuscript path" ;
    rdfs:comment "Path to the manuscript file within the source repository." .


# =============================================================================
# PROPERTIES — Author metadata (extending PRO/FOAF)
# =============================================================================

od:isDeceased
    rdf:type owl:DatatypeProperty ;
    rdfs:domain foaf:Person ;
    rdfs:range xsd:boolean ;
    rdfs:label "deceased" ;
    rdfs:comment "True if this person is deceased. Rendered with the ‡ symbol in bylines." .


# =============================================================================
# CREDiT ALIGNMENT — the 14 NISO CRediT contributor roles (ADR-021)
#
# Declared as pro:Role instances so authorship role nodes can point at
# them via pro:withRole. See https://credit.niso.org/.
# =============================================================================

credit:conceptualization a pro:Role ; rdfs:label "Conceptualization" .
credit:data-curation a pro:Role ; rdfs:label "Data Curation" .
credit:formal-analysis a pro:Role ; rdfs:label "Formal Analysis" .
credit:funding-acquisition a pro:Role ; rdfs:label "Funding Acquisition" .
credit:investigation a pro:Role ; rdfs:label "Investigation" .
credit:methodology a pro:Role ; rdfs:label "Methodology" .
credit:project-administration a pro:Role ; rdfs:label "Project Administration" .
credit:resources a pro:Role ; rdfs:label "Resources" .
credit:software a pro:Role ; rdfs:label "Software" .
credit:supervision a pro:Role ; rdfs:label "Supervision" .
credit:validation a pro:Role ; rdfs:label "Validation" .
credit:visualization a pro:Role ; rdfs:label "Visualization" .
credit:writing-original-draft a pro:Role ; rdfs:label "Writing – Original Draft" .
credit:writing-review-editing a pro:Role ; rdfs:label "Writing – Review & Editing" .

objects.c97602e366b7e9f7adda5c92d99502e80cc52659:
# OpenDraft Registry SHACL Shapes
#
# A registry is a fabio:ExpressionCollection. Its frbr:part values must
# be either only publications (a publication registry) or only other
# registries (a collection registry) — never both (OD-013, OD-014).
# Registries replace the deleted od:Registry class hierarchy (ADR-018).

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix od: <https://w3id.org/opendraft/ontology#> .
@prefix fabio: <http://purl.org/spar/fabio/> .
@prefix frbr: <http://purl.org/vocab/frbr/core#> .

# =============================================================================
# Registry Shape
# =============================================================================

od:RegistryShape
    a sh:NodeShape ;
    sh:targetClass fabio:ExpressionCollection ;
    sh:xone (
        [ a sh:NodeShape ;
          sh:property [
              sh:path frbr:part ;
              sh:minCount 1 ;
              sh:class od:Publication ;
              sh:message "A publication registry must only contain publications in frbr:part." ;
          ] ]
        [ a sh:NodeShape ;
          sh:property [
              sh:path frbr:part ;
              sh:minCount 1 ;
              sh:class fabio:ExpressionCollection ;
              sh:message "A collection registry must only contain registries in frbr:part." ;
          ] ]
    ) .

objects.120c887ee86c70ac8e222b2fe96b82a32fa3839c:
# OpenDraft Example: Collection Registry
#
# A working example of a collection registry (OD-013). It is a
# fabio:ExpressionCollection that references exactly one child
# registry by IRI and must not directly contain publications.
#
# Validates clean against protocol/registry.shacl.ttl.

@prefix od: <https://w3id.org/opendraft/ontology#> .
@prefix fabio: <http://purl.org/spar/fabio/> .
@prefix frbr: <http://purl.org/vocab/frbr/core#> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix foaf: <http://xmlns.com/foaf/0.1/> .

# The collection registry itself. A discovery root that lists child
# registries instead of publications.
<https://example.org/example-collection-registry>
    a fabio:ExpressionCollection ;
    dcterms:title "OpenDraft Example Collection Registry" ;
    dcterms:description "A top-level collection registry for demonstration purposes." ;
    frbr:part <https://example.org/example-publication-registry> ;
    foaf:homepage <https://github.com/konsulin-care/opendraft> .

# The child publication registry, typed here so this file validates
# standalone: every frbr:part value must be typed, and every
# fabio:ExpressionCollection must itself carry frbr:part values of
# exactly one kind.
<https://example.org/example-publication-registry>
    a fabio:ExpressionCollection ;
    frbr:part <https://example.org/example-publication> .

# The referenced article, typed inline for the same reason. Its full
# description lives in protocol/examples/article.ttl.
<https://example.org/example-publication>
    a od:Publication .

objects.5914adcf72edbaa8761e70c85bfd944382df4145:
# OpenDraft Article Release SHACL Shapes
#
# Release-only constraints split out of protocol/article.shacl.ttl
# (T26): a draft validates against article.shacl.ttl alone, a release
# against the union of both files. A graph is a release iff its
# od:Publication carries a DOI identifier (dcterms:identifier or
# datacite:hasIdentifier) or realizes a fabio:Work via
# frbr:realizationOf. Drafts may omit the repository URL and source
# revision; releases must declare them.
# SHACL Core only (no SHACL-SPARQL); assumes one publication per graph.

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix od: <https://w3id.org/opendraft/ontology#> .
@prefix fabio: <http://purl.org/spar/fabio/> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix frbr: <http://purl.org/vocab/frbr/core#> .
@prefix datacite: <http://purl.org/datacite/ontology/> .
@prefix literal: <https://w3id.org/literal/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix doco: <http://purl.org/spar/doco/> .

# =============================================================================
# Release Provenance Shape — repository URL and source revision
#
# Split from od:PublicationShape: drafts compile without a repository
# or a pinned Git commit, releases must record both (ADR-018).
# =============================================================================

od:PublicationReleaseShape
    a sh:NodeShape ;
    sh:targetClass od:Publication ;

    sh:property [
        sh:path od:repositoryUrl ;
        sh:datatype xsd:anyURI ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:message "A release must have exactly one repository URL with datatype xsd:anyURI." ;
    ] ;
    sh:property [
        sh:path od:sourceRevision ;
        sh:datatype xsd:string ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:pattern "^[0-9a-f]{40}$" ;
        sh:message "A release must have exactly one source revision: a 40-character hexadecimal Git commit SHA." ;
    ] .

# =============================================================================
# Work / Version Shape — FRBR Work–Expression model (ADR-021)
#
# The manuscript is a fabio:Work (concept DOI); each published version
# is an od:Publication that realizes exactly one Work and may revise at
# most one earlier version. A publication IRI can never double as its
# own Work IRI (concept and version DOIs must differ).
# =============================================================================

od:PublicationWorkShape
    a sh:NodeShape ;
    sh:targetClass od:Publication ;

    sh:property [
        sh:path frbr:realizationOf ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:qualifiedValueShape [
            a sh:NodeShape ;
            sh:class fabio:Work ;
        ] ;
        sh:qualifiedMinCount 1 ;
        sh:message "A release must have exactly one frbr:realizationOf pointing to a fabio:Work." ;
    ] ;
    sh:property [
        sh:path frbr:revisionOf ;
        sh:maxCount 1 ;
        sh:message "A release may revise at most one earlier version (frbr:revisionOf)." ;
    ] ;
    sh:not [
        a sh:NodeShape ;
        sh:class fabio:Work ;
    ] ;
    sh:message "A publication IRI must differ from its Work IRI: an od:Publication may not also be a fabio:Work." .

# =============================================================================
# Identifier Shape — classic dcterms:identifier or OCDM identifier nodes
# =============================================================================

od:PublicationIdentifierShape
    a sh:NodeShape ;
    sh:targetClass od:Publication ;

    sh:property [
        sh:path datacite:hasIdentifier ;
        sh:node [
            a sh:NodeShape ;
            sh:property [
                sh:path datacite:usesIdentifierScheme ;
                sh:minCount 1 ;
                sh:message "An OCDM identifier node must declare datacite:usesIdentifierScheme." ;
            ] ;
            sh:property [
                sh:path literal:hasLiteralValue ;
                sh:minCount 1 ;
                sh:message "An OCDM identifier node must declare literal:hasLiteralValue." ;
            ] ;
        ] ;
        sh:message "A datacite:hasIdentifier node must declare a scheme and a literal value." ;
    ] ;
    sh:or (
        [ sh:property [ sh:path dcterms:identifier ; sh:minCount 1 ] ]
        [ sh:property [ sh:path datacite:hasIdentifier ; sh:minCount 1 ] ]
    ) ;
    sh:message "A release must declare at least one identifier: dcterms:identifier or an OCDM datacite:hasIdentifier node." .

# =============================================================================
# Section Source Shape — releases pin every section to its block file
#
# Drafts may omit section sources (article.shacl.ttl allows an
# optional https dcterms:source); a release must declare the raw
# block-file URL for every doco:Section (ADR-018 provenance).
# =============================================================================

od:SectionSourceShape
    a sh:NodeShape ;
    sh:targetClass doco:Section ;

    sh:property [
        sh:path dcterms:source ;
        sh:minCount 1 ;
        sh:message "A release section must declare its dcterms:source block file IRI." ;
    ] .

objects.42acd946f331e8870b9f772aa21d49eac3ee7ff1:
# OpenDraft Article SHACL Shapes
#
# Validates that an article RDF graph conforms to the OpenDraft protocol.
# Phase 01: full required field set plus optional-field capability shapes.
# Provenance scalars live directly on od:Publication (see ADR-018).
# Release-only constraints (identifier, FRBR work, od:repositoryUrl,
# od:sourceRevision) live in protocol/article-release.shacl.ttl.
# ADR-021: authorship follows the OCDM role model — every role node is
# linked from the publication via pro:isDocumentContextFor, roles are
# held by agents (pro:isHeldBy), and author order is an oco:hasNext
# chain between roles carrying pro:withRole pro:author.
# SHACL Core only (no SHACL-SPARQL); assumes one publication per graph.

@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix od: <https://w3id.org/opendraft/ontology#> .
@prefix fabio: <http://purl.org/spar/fabio/> .
@prefix dcterms: <http://purl.org/dc/terms/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix doco: <http://purl.org/spar/doco/> .
@prefix deo: <http://purl.org/spar/deo/> .
@prefix pro: <http://purl.org/spar/pro/> .
@prefix scoro: <http://purl.org/spar/scoro/> .
@prefix oco: <https://w3id.org/oc/ontology/> .
@prefix foaf: <http://xmlns.com/foaf/0.1/> .
@prefix credit: <https://credit.niso.org/contributor-roles/> .
@prefix frbr: <http://purl.org/vocab/frbr/core#> .
@prefix cito: <http://purl.org/spar/cito/> .
@prefix datacite: <http://purl.org/datacite/ontology/> .
@prefix literal: <https://w3id.org/literal/> .
@prefix prism: <http://prismstandard.org/namespaces/basic/2.0/> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

# =============================================================================
# Publication Shape — required fields
# =============================================================================

od:PublicationShape
    a sh:NodeShape ;
    sh:targetClass od:Publication ;

    sh:property [
        sh:path dcterms:title ;
        sh:datatype xsd:string ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:message "A publication must have exactly one title." ;
    ] ;
    sh:property [
        sh:path dcterms:creator ;
        sh:minCount 1 ;
        sh:message "A publication must have at least one creator." ;
    ] ;
    sh:property [
        sh:path od:manuscriptPath ;
        sh:datatype xsd:string ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:message "A publication must have exactly one manuscript path." ;
    ] ;
    sh:property [
        sh:path dcterms:conformsTo ;
        sh:nodeKind sh:IRI ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:pattern "^https://github\\.com/[^/]+/[^/]+/tree/[0-9a-f]{40}/protocol$" ;
        sh:message "A publication must have exactly one dcterms:conformsTo IRI: https://github.com/<owner>/<repo>/tree/<40-character SHA>/protocol." ;
    ] ;
    sh:property [
        sh:path dcterms:hasPart ;
        sh:class doco:Section ;
        sh:message "dcterms:hasPart values must be doco:Section nodes." ;
    ] .
    # Release-only constraints (identifier, frbr:realizationOf,
    # od:repositoryUrl, od:sourceRevision) live in
    # protocol/article-release.shacl.ttl; drafts validate without them.

# =============================================================================
# License and Citation Shapes — warnings (do not affect conformance)
# =============================================================================

od:PublicationLicenseShape
    a sh:NodeShape ;
    sh:targetClass od:Publication ;

    sh:property [
        sh:path dcterms:license ;
        sh:minCount 1 ;
        sh:severity sh:Warning ;
        sh:message "A publication should declare a dcterms:license." ;
    ] .

od:PublicationCitationShape
    a sh:NodeShape ;
    sh:targetClass od:Publication ;

    sh:property [
        sh:path cito:cites ;
        sh:not [
            a sh:NodeShape ;
            sh:class fabio:Work ;
        ] ;
        sh:severity sh:Warning ;
        sh:message "cito:cites should target a specific version (version DOI), not the fabio:Work concept." ;
    ] .

# =============================================================================
# Publication Shape — optional fields
# =============================================================================

od:PublicationOptionalShape
    a sh:NodeShape ;
    sh:targetClass od:Publication ;

    sh:property [
        sh:path dcterms:abstract ;
        sh:maxCount 1 ;
        sh:message "A publication may have at most one abstract." ;
    ] .

# =============================================================================
# Publication Shape — informational (non-enforcing) capability notes
# =============================================================================

od:PublicationInfoShape
    a sh:NodeShape ;
    sh:targetClass od:Publication ;
    sh:severity sh:Info ;

    sh:property [
        sh:path fabio:hasSubjectTerm ;
        sh:message "Subject terms may be expressed via fabio:hasSubjectTerm pointing to a SKOS subject term." ;
    ] ;
    sh:property [
        sh:path prism:keyword ;
        sh:message "Keywords are informational and may be expressed via prism:keyword." ;
    ] ;
    sh:property [
        sh:path dcterms:references ;
        sh:message "References may be expressed via dcterms:references." ;
    ] .

# =============================================================================
# Authorship Shapes — OCDM author role model (ADR-021)
#
# Authorship roles are pro:RoleInTime nodes reachable from the
# publication via pro:isDocumentContextFor. The author order is a single
# oco:hasNext chain between roles carrying pro:withRole pro:author.
# =============================================================================

od:PublicationAuthorshipShape
    a sh:NodeShape ;
    sh:targetClass od:Publication ;

    # At least one author role in the document context.
    sh:property [
        sh:path pro:isDocumentContextFor ;
        sh:qualifiedValueShape [
            sh:path pro:withRole ;
            sh:hasValue pro:author ;
        ] ;
        sh:qualifiedMinCount 1 ;
        sh:message "A publication must have at least one author role (pro:withRole pro:author)." ;
    ] ;

    # Exactly one author role heads the chain (no incoming oco:hasNext).
    sh:property [
        sh:path pro:isDocumentContextFor ;
        sh:qualifiedValueShape [
            a sh:NodeShape ;
            sh:property [
                sh:path pro:withRole ;
                sh:hasValue pro:author ;
            ] ;
            sh:property [
                sh:path [ sh:inversePath oco:hasNext ] ;
                sh:maxCount 0 ;
            ] ;
        ] ;
        sh:qualifiedMinCount 1 ;
        sh:message "Exactly one author role must head the oco:hasNext author chain." ;
    ] ;
    sh:property [
        sh:path pro:isDocumentContextFor ;
        sh:qualifiedValueShape [
            a sh:NodeShape ;
            sh:property [
                sh:path pro:withRole ;
                sh:hasValue pro:author ;
            ] ;
            sh:property [
                sh:path [ sh:inversePath oco:hasNext ] ;
                sh:maxCount 0 ;
            ] ;
        ] ;
        sh:qualifiedMaxCount 1 ;
        sh:message "Exactly one author role may head the oco:hasNext author chain." ;
    ] ;

    # An author role must be held by a named agent (person or group).
    sh:property [
        sh:path pro:isDocumentContextFor ;
        sh:qualifiedValueShape [
            a sh:NodeShape ;
            sh:property [
                sh:path pro:withRole ;
                sh:hasValue pro:author ;
            ] ;
            sh:property [
                sh:path pro:isHeldBy ;
                sh:not [
                    a sh:NodeShape ;
                    sh:or (
                        [ sh:path foaf:familyName ; sh:minCount 1 ]
                        [ sh:path foaf:name ; sh:minCount 1 ]
                    ) ;
                ] ;
            ] ;
        ] ;
        sh:qualifiedMaxCount 0 ;
        sh:message "An author role must be held by an agent with a foaf:familyName or foaf:name." ;
    ] ;

    # A person author must hold a scoro:affiliate role (groups exempt).
    sh:property [
        sh:path pro:isDocumentContextFor ;
        sh:qualifiedValueShape [
            a sh:NodeShape ;
            sh:property [
                sh:path pro:withRole ;
                sh:hasValue pro:author ;
            ] ;
            sh:property [
                sh:path pro:isHeldBy ;
                sh:not [
                    a sh:NodeShape ;
                    sh:or (
                        [ sh:class foaf:Group ]
                        [ sh:property [
                            sh:path [ sh:inversePath pro:isHeldBy ] ;
                            sh:qualifiedValueShape [
                                sh:path pro:withRole ;
                                sh:hasValue scoro:affiliate ;
                            ] ;
                            sh:qualifiedMinCount 1 ;
                        ] ]
                    ) ;
                ] ;
            ] ;
        ] ;
        sh:qualifiedMaxCount 0 ;
        sh:message "A person author must hold a scoro:affiliate role linked to an organization." ;
    ] ;

    # An affiliate role has exactly one organization with a foaf:name;
    # no context role may be an affiliate role lacking one.
    sh:property [
        sh:path pro:isDocumentContextFor ;
        sh:qualifiedValueShape [
            a sh:NodeShape ;
            sh:property [
                sh:path pro:withRole ;
                sh:hasValue scoro:affiliate ;
            ] ;
            sh:not [
                a sh:NodeShape ;
                sh:property [
                    sh:path pro:relatesToOrganization ;
                    sh:minCount 1 ;
                    sh:maxCount 1 ;
                    sh:node [
                        sh:property [
                            sh:path foaf:name ;
                            sh:minCount 1 ;
                        ] ;
                    ] ;
                ] ;
            ] ;
        ] ;
        sh:qualifiedMaxCount 0 ;
        sh:message "An affiliate role must have exactly one organization with a foaf:name." ;
    ] ;

    # At least one corresponding-author role whose holder has a mailbox.
    sh:property [
        sh:path pro:isDocumentContextFor ;
        sh:qualifiedValueShape [
            a sh:NodeShape ;
            sh:property [
                sh:path pro:withRole ;
                sh:hasValue scoro:corresponding-author ;
            ] ;
            sh:property [
                sh:path pro:isHeldBy ;
                sh:qualifiedValueShape [
                    sh:path foaf:mbox ;
                    sh:minCount 1 ;
                ] ;
                sh:qualifiedMinCount 1 ;
            ] ;
        ] ;
        sh:qualifiedMinCount 1 ;
        sh:message "A publication must have at least one corresponding-author role whose holder has a foaf:mbox." ;
    ] .

# On-behalf-of authors are modeled as an extra scoro:agent role in the
# document context: held by the author (pro:isHeldBy) and related to the
# group (pro:relatesToEntity). It never joins the oco:hasNext chain —
# the chain shapes above only match roles carrying pro:withRole pro:author.
od:AuthorshipRoleShape
    a sh:NodeShape ;
    sh:targetClass pro:RoleInTime ;

    sh:property [
        sh:path pro:isHeldBy ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:message "Every authorship role must have exactly one holder (pro:isHeldBy)." ;
    ] ;
    sh:property [
        sh:path oco:hasNext ;
        sh:maxCount 1 ;
        sh:message "A role may have at most one successor in the author chain (oco:hasNext)." ;
    ] ;
    sh:property [
        sh:path [ sh:inversePath oco:hasNext ] ;
        sh:maxCount 1 ;
        sh:message "A role may have at most one predecessor in the author chain." ;
    ] ;
    sh:property [
        sh:path pro:withRole ;
        sh:in (
            pro:author
            scoro:agent
            scoro:corresponding-author
            scoro:affiliate
            scoro:consortium-author
            credit:conceptualization
            credit:data-curation
            credit:formal-analysis
            credit:funding-acquisition
            credit:investigation
            credit:methodology
            credit:project-administration
            credit:resources
            credit:software
            credit:supervision
            credit:validation
            credit:visualization
            credit:writing-original-draft
            credit:writing-review-editing
        ) ;
        sh:message "Role values (pro:withRole) are restricted to PRO/SCoRO authorship roles and the 14 NISO CRediT roles." ;
    ] .

od:GroupShape
    a sh:NodeShape ;
    sh:targetClass foaf:Group ;

    sh:property [
        sh:path foaf:name ;
        sh:minCount 1 ;
        sh:message "A foaf:Group author must have a foaf:name." ;
    ] .

# =============================================================================
# Section Shape — manuscript sections (doco:Section, deo roles)
#
# A section is linked from its publication via dcterms:hasPart,
# titled exactly once, carrying at most one deo role class, chained
# to its successor with oco:hasNext, and sourced over https. The
# release-only dcterms:source requirement lives in
# protocol/article-release.shacl.ttl.
# =============================================================================

od:SectionShape
    a sh:NodeShape ;
    sh:targetClass doco:Section ;

    sh:property [
        sh:path dcterms:title ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:message "A section must have exactly one dcterms:title." ;
    ] ;
    sh:property [
        sh:path rdf:type ;
        sh:qualifiedValueShape [
            sh:in (
                deo:Introduction
                deo:Methods
                deo:Results
                deo:Discussion
                deo:Conclusion
                deo:Acknowledgements
                deo:AuthorContribution
                deo:Background
                deo:Biography
                deo:Contribution
                deo:Data
                deo:DatasetDescription
                deo:Dedication
                deo:Epilogue
                deo:Evaluation
                deo:ExternalResourceDescription
                deo:FutureWork
                deo:Materials
                deo:Model
                deo:Motivation
                deo:Postscript
                deo:ProblemStatement
                deo:Prologue
                deo:RelatedWork
                deo:Scenario
                deo:SupplementaryInformationDescription
            ) ;
        ] ;
        sh:qualifiedMaxCount 1 ;
        sh:message "A section may have at most one deo role class." ;
    ] ;
    sh:property [
        sh:path oco:hasNext ;
        sh:maxCount 1 ;
        sh:class doco:Section ;
        sh:message "A section may have at most one successor section (oco:hasNext)." ;
    ] ;
    sh:property [
        sh:path [ sh:inversePath oco:hasNext ] ;
        sh:maxCount 1 ;
        sh:message "A section may have at most one predecessor section (oco:hasNext)." ;
    ] ;
    sh:property [
        sh:path dcterms:source ;
        sh:maxCount 1 ;
        sh:nodeKind sh:IRI ;
        sh:pattern "^https://" ;
        sh:message "A section dcterms:source must be an IRI starting with https://." ;
    ] .
